"""Generate c/tables_q15.c from tables.py so C and Python use identical ROM tables."""
from pathlib import Path

from tables import N_FFT, N_PILOT, twiddles_q15, pilot_signs


def c_array(ctype, name, size, values):
    body = ", ".join(str(int(v)) for v in values)
    return f"const {ctype} {name}[{size}] = {{ {body} }};\n"


def main():
    tw_re, tw_im = twiddles_q15()
    out = Path(__file__).resolve().parent.parent / "c" / "tables_q15.c"
    out.write_text(
        "/* tables_q15.c - generated by python/gen_tables.py, do not edit */\n"
        '#include "ofdm.h"\n\n'
        + c_array("int16_t", "TW_RE", "N_FFT / 2", tw_re)
        + c_array("int16_t", "TW_IM", "N_FFT / 2", tw_im)
        + c_array("int8_t", "PILOT_SIGN", "N_PILOT", pilot_signs())
    )
    assert len(tw_re) == N_FFT // 2 and len(pilot_signs()) == N_PILOT
    print(f"wrote {out}")


if __name__ == "__main__":
    main()
